	(axis cs:-6,0)
	arc[start angle=180, end angle=0, radius={transformdirectionx(2)}];

	% Part 2: line segment from (-2,0) to (2,-4)
	\draw[deepskyblue, solid, line width=1pt] (axis cs:-2,0) -- (axis cs:2,-4);

